  backdrop-filter: blur(10px);
}

.logo {
  font-family: var(--font-heading);
  font-size: 2rem;
  color: var(--red);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.lang-select {
  background: rgba(0,0,0,0.6);
  border: 1px solid var(--border);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 0.875rem;
  cursor: pointer;
  font-family: var(--font-body);
}

.lang-select option { background: var(--bg); }

.btn-sign-in {
  background: var(--red);
  color: var(--white);
  border: none;
  padding: 8px 20px;
  border-radius: 4px;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
  font-family: var(--font-body);
}

.btn-sign-in:hover { background: var(--red-hover); }

/* ─── Hero ─── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 24px 60px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, #000 0%, transparent 40%),
    linear-gradient(to bottom, rgba(0,0,0,0.7) 0%, transparent 40%),
    linear-gradient(to right, rgba(0,0,0,0.5), transparent 50%, rgba(0,0,0,0.5)),
    url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect fill="%23111" width="800" height="600"/><rect fill="%23181818" x="20" y="20" width="180" height="260" rx="8" transform="rotate(-8 110 150)"/><rect fill="%23222" x="220" y="40" width="160" height="240" rx="8" transform="rotate(5 300 160)"/><rect fill="%231a1a1a" x="420" y="30" width="170" height="250" rx="8" transform="rotate(-3 505 155)"/><rect fill="%23202020" x="600" y="50" width="160" height="230" rx="8" transform="rotate(7 680 165)"/><rect fill="%23151515" x="80" y="310" width="175" height="250" rx="8" transform="rotate(4 167 435)"/><rect fill="%231e1e1e" x="290" y="320" width="165" height="240" rx="8" transform="rotate(-6 372 440)"/><rect fill="%23191919" x="490" y="300" width="180" height="260" rx="8" transform="rotate(3 580 430)"/></svg>');
  background-size: cover;
  background-position: center;
  z-index: 0;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 7vw, 5rem);
  letter-spacing: 2px;
  line-height: 1.05;
  margin-bottom: 16px;
