  padding: 16px 16px;
  background: rgba(22,22,22,0.8);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--white);
  font-size: 1rem;
  font-family: var(--font-body);
  outline: none;
  transition: border-color 0.2s;
}

.email-form input[type="email"]:focus {
  border-color: var(--white-muted);
}

.email-form input[type="email"]::placeholder {
  color: var(--white-dim);
}

.btn-get-started {
  background: var(--red);
  color: var(--white);
  border: none;
  padding: 16px 28px;
  border-radius: 4px;
  font-size: 1.125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
  white-space: nowrap;
  font-family: var(--font-body);
}

.btn-get-started:hover { background: var(--red-hover); }

/* ─── Section divider ─── */
.section-divider {
  height: 8px;
  background: var(--bg-elevated);
}

/* ─── Trending ─── */
.trending {
  padding: 56px 48px 64px;
  background: var(--bg);
}

.trending-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
}

.section-title {
  font-family: var(--font-heading);
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  letter-spacing: 1.5px;
}

.carousel-controls {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: rgba(20,20,20,0.8);
  color: var(--white);
  font-size: 1.25rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: rgba(255,255,255,0.1);
  border-color: var(--white-muted);
}

.carousel-track-wrapper {
  overflow: hidden;
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 12px;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  cursor: grab;
}

.carousel-track.dragging { cursor: grabbing; transition: none; }

.trending-card {
  flex: 0 0 auto;
  width: 220px;
  position: relative;
  border-radius: 6px;
  overflow: hidden;
  transition: transform 0.3s;
}

.trending-card:hover { transform: scale(1.05); }

.trending-card-bg {
  width: 100%;
  aspect-ratio: 2/3;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.trending-rank {
  position: absolute;
  bottom: -10px;
  left: -5px;
  font-family: var(--font-heading);
  font-size: 8rem;
  line-height: 1;
  color: rgba(255,255,255,0.08);
  letter-spacing: -4px;
  pointer-events: none;
  user-select: none;
}

.trending-card-bg .poster-art {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 16px 12px;
  background: linear-gradient(135deg, var(--card-color-1, #1a1a2e) 0%, var(--card-color-2, #16213e) 100%);
}

.trending-title {
  font-size: 0.875rem;
  font-weight: 700;
  text-align: center;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
  position: relative;
  z-index: 1;
}

.poster-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, transparent 60%);
}

/* ─── Features ─── */
.features {
  padding: 56px 48px 64px;
  background: var(--bg);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
}

.feature-card {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: 12px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 260px;
  transition: transform 0.3s, box-shadow 0.3s;
  position: relative;
  overflow: hidden;
}

.feature-card::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, rgba(229,9,20,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.5);
}

.feature-title {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 12px;
  line-height: 1.3;
}

.feature-desc {
  font-size: 0.9375rem;
  color: var(--white-muted);
  line-height: 1.5;
}

.feature-icon {
  align-self: flex-end;
  margin-top: 24px;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--white-dim);
  background: rgba(255,255,255,0.05);
  border-radius: 8px;
}

/* ─── FAQ ─── */
.faq {
  padding: 56px 48px 64px;
  background: var(--bg);
}

.faq-list {
  max-width: 800px;
  margin: 32px auto 0;
}

.faq-item {
  margin-bottom: 6px;
}

.faq-question {
  width: 100%;
  background: var(--bg-elevated);
  border: none;
  color: var(--white);
  font-size: 1.125rem;
  font-weight: 500;
  padding: 20px 56px 20px 24px;
  text-align: left;
  cursor: pointer;
  position: relative;
  transition: background 0.2s;
  font-family: var(--font-body);
  border-radius: 2px;
}

.faq-question:hover { background: #1f1f1f; }

.faq-question::after {
  content: '+';
  position: absolute;
  right: 24px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 1.75rem;
  font-weight: 300;
  transition: transform 0.3s;
  color: var(--white-muted);
}

.faq-item.open .faq-question::after {
  transform: translateY(-50%) rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  background: var(--bg-elevated);
}

.faq-answer-inner {
  padding: 20px 24px;
  font-size: 1rem;
  color: var(--white-muted);
  line-height: 1.6;
}

.faq-item.open .faq-answer {
  max-height: 400px;
}

/* ─── CTA Bottom ─── */
.cta-bottom {
  padding: 56px 24px;
  background: var(--bg);
  text-align: center;
}

.cta-bottom .hero-prompt {
  margin-bottom: 20px;
}

/* ─── Footer ─── */
.site-footer {
  padding: 48px;
  background: var(--bg);
  border-top: 1px solid var(--border);
}

.footer-contact {
  color: var(--white-muted);
  font-size: 0.9375rem;
  margin-bottom: 28px;
}

.footer-contact a { color: var(--white-muted); text-decoration: underline; }

.footer-links {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 32px;
}

.footer-links a {
  font-size: 0.8125rem;
  color: var(--white-dim);
  transition: color 0.2s;
}

.footer-links a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-legal {
  font-size: 0.75rem;
  color: var(--white-dim);
  max-width: 400px;
}

.footer-legal a { color: var(--white-dim); text-decoration: underline; }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .site-header { padding: 16px 20px; }
  .logo { font-size: 1.5rem; }
  .trending { padding: 40px 20px 48px; }
  .features { padding: 40px 20px 48px; }
